const i=[{id:"bronchodilators-antihistamines-001",topicId:"bronchodilators-antihistamines",question:"Что такое бронходилататоры?",options:["Препараты, которые расширяют просвет бронхов и облегчают дыхание","Препараты, разжижающие густую вязкую мокроту","Препараты, подавляющие кашлевой рефлекс","Препараты, блокирующие действие гистамина"],correctIndex:0,explanation:"Бронходилататоры — это препараты, которые расширяют просвет бронхов и облегчают дыхание.",difficulty:"easy",tags:["бронходилататоры","определение"]},{id:"bronchodilators-antihistamines-002",topicId:"bronchodilators-antihistamines",question:"Каков механизм действия бронходилататоров?",options:["Уменьшают выработку слизи в бронхах","Снимают спазм гладкой мускулатуры бронхов и уменьшают сопротивление дыхательных путей","Подавляют кашлевой центр в продолговатом мозге","Уничтожают бактериальную микрофлору дыхательных путей"],correctIndex:1,explanation:"Бронходилататоры снимают спазм гладкой мускулатуры бронхов, уменьшают сопротивление дыхательных путей и улучшают вентиляцию лёгких.",difficulty:"medium",tags:["бронходилататоры","фармакология"]},{id:"bronchodilators-antihistamines-003",topicId:"bronchodilators-antihistamines",question:"Что означает термин «дилатация»?",options:["Сужение","Воспаление","Расширение","Разжижение"],correctIndex:2,explanation:"Дилатация — расширение. Отсюда название группы: бронходилататоры — расширяющие бронхи препараты.",difficulty:"easy",tags:["терминология"]},{id:"bronchodilators-antihistamines-004",topicId:"bronchodilators-antihistamines",question:"При каких состояниях применяются бронходилататоры?",options:["При артериальной гипертензии и аритмии","При гастрите и язвенной болезни","При тромбозе и кровотечениях","При бронхиальной астме, ХОБЛ и обострениях бронхоспазма"],correctIndex:3,explanation:"Бронходилататоры используются при бронхиальной астме, ХОБЛ, обострениях бронхоспазма и некоторых острых инфекциях дыхательных путей.",difficulty:"medium",tags:["бронходилататоры","показания"]},{id:"bronchodilators-antihistamines-005",topicId:"bronchodilators-antihistamines",question:"Какое влияние оказывают бронходилататоры на вентиляцию лёгких?",options:["Улучшают её","Ухудшают её","Не влияют на неё","Полностью останавливают её на время действия"],correctIndex:0,explanation:"Бронходилататоры улучшают вентиляцию лёгких за счёт расширения бронхов и уменьшения сопротивления дыхательных путей.",difficulty:"easy",tags:["бронходилататоры","фармакология"]},{id:"bronchodilators-antihistamines-006",topicId:"bronchodilators-antihistamines",question:"Какие побочные эффекты со стороны сердечно-сосудистой системы вызывают бронходилататоры?",options:["Брадикардию и снижение давления","Сердцебиение и тахикардию","Полную блокаду проводимости","Остановку сердца"],correctIndex:1,explanation:"К побочным эффектам бронходилататоров относятся сердцебиение и тахикардия.",difficulty:"medium",tags:["бронходилататоры","побочные эффекты"]},{id:"bronchodilators-antihistamines-007",topicId:"bronchodilators-antihistamines",question:"Какой побочный эффект бронходилататоров проявляется со стороны мышц кистей?",options:["Судороги пальцев","Полный паралич","Тремор рук","Онемение кончиков пальцев"],correctIndex:2,explanation:"Одним из побочных эффектов бронходилататоров является тремор рук.",difficulty:"medium",tags:["бронходилататоры","побочные эффекты"]},{id:"bronchodilators-antihistamines-008",topicId:"bronchodilators-antihistamines",question:"Какие психоэмоциональные побочные эффекты характерны для бронходилататоров?",options:["Апатия и сонливость","Полное безразличие к окружающему","Депрессивное настроение","Чувство тревоги и возбуждение"],correctIndex:3,explanation:"К побочным эффектам бронходилататоров относятся чувство тревоги и возбуждение, а также головная боль.",difficulty:"medium",tags:["бронходилататоры","побочные эффекты"]},{id:"bronchodilators-antihistamines-009",topicId:"bronchodilators-antihistamines",question:"Что такое ингаляция?",options:["Способ введения лекарственных веществ через дыхательные пути в виде аэрозоля, пара или мелких капель","Введение препарата под язык до полного рассасывания","Введение лекарства в прямую кишку","Внутривенное капельное введение растворов"],correctIndex:0,explanation:"Ингаляция — это способ введения лекарственных веществ через дыхательные пути в виде аэрозоля, пара или мелких капель с помощью специального аппарата.",difficulty:"easy",tags:["ингаляция","определение"]},{id:"bronchodilators-antihistamines-010",topicId:"bronchodilators-antihistamines",question:"Что представляет собой небулайзер?",options:["Прибор для измерения объёма выдыхаемого воздуха","Устройство, превращающее жидкое лекарство в мелкодисперсный аэрозоль","Аппарат для искусственной вентиляции лёгких","Датчик для определения насыщения крови кислородом"],correctIndex:1,explanation:"Небулайзер — устройство, которое превращает жидкое лекарство в мелкодисперсный аэрозоль.",difficulty:"easy",tags:["небулайзер","определение"]},{id:"bronchodilators-antihistamines-011",topicId:"bronchodilators-antihistamines",question:"Какое преимущество обеспечивает применение небулайзера?",options:["Полное отсутствие побочных эффектов препаратов","Возможность вводить препараты без назначения врача","Глубокое проникновение препарата в дыхательные пути и пригодность для пациентов любого возраста","Мгновенное попадание препарата в кровоток, минуя лёгкие"],correctIndex:2,explanation:"Небулайзер обеспечивает глубокое проникновение препарата в дыхательные пути и подходит для пациентов любого возраста.",difficulty:"medium",tags:["небулайзер","преимущества"]},{id:"bronchodilators-antihistamines-012",topicId:"bronchodilators-antihistamines",question:"Какая часть небулайзера создаёт поток воздуха для распыления лекарства?",options:["Фильтр","Маска","Камера для лекарства","Компрессор"],correctIndex:3,explanation:"В состав небулайзера входит компрессор, а также камера для лекарства, воздушная трубка, маски и фильтр.",difficulty:"medium",tags:["небулайзер","устройство"]},{id:"bronchodilators-antihistamines-013",topicId:"bronchodilators-antihistamines",question:"Сколько масок входит в комплект небулайзера и для кого они предназначены?",options:["Две — для взрослых и детей","Одна универсальная для всех возрастов","Три — для взрослых, детей и новорождённых","Четыре — по размеру лица пациента"],correctIndex:0,explanation:"В состав небулайзера входят 2 маски — для взрослых и детей.",difficulty:"medium",tags:["небулайзер","устройство"]},{id:"bronchodilators-antihistamines-014",topicId:"bronchodilators-antihistamines",question:"Какие элементы, помимо компрессора и камеры для лекарства, входят в состав небулайзера?",options:["Манометр и редуктор давления","Воздушная трубка (шланг), маски и фильтр","Игла и катетер для внутривенного введения","Датчик пульса и экран для отображения сатурации"],correctIndex:1,explanation:"Небулайзер состоит из компрессора, камеры для лекарства, воздушной трубки (шланга), 2 масок и фильтра.",difficulty:"medium",tags:["небулайзер","устройство"]},{id:"bronchodilators-antihistamines-015",topicId:"bronchodilators-antihistamines",question:"С какой целью через небулайзер вводят физиологический раствор?",options:["Для расширения бронхов","Для подавления кашлевого рефлекса","Для увлажнения","Для уничтожения бактерий"],correctIndex:2,explanation:"Физиологический раствор вводят через небулайзер для увлажнения дыхательных путей.",difficulty:"medium",tags:["небулайзер","препараты"]},{id:"bronchodilators-antihistamines-016",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество из перечисленных вводится через небулайзер?",options:["Лоратадин","Дифенгидрамин","Кодеин","Ипратропий"],correctIndex:3,explanation:"Через небулайзер обычно вводят ипратропий, будесонид и другие препараты, а также физиологический раствор для увлажнения.",difficulty:"medium",tags:["небулайзер","препараты"]},{id:"bronchodilators-antihistamines-017",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество из группы глюкокортикостероидов вводится через небулайзер?",options:["Будесонид","Сальбутамол","Теофиллин","Клемастин"],correctIndex:0,explanation:"Через небулайзер вводят будесонид — глюкокортикостероид для ингаляционного применения.",difficulty:"medium",tags:["небулайзер","препараты"]},{id:"bronchodilators-antihistamines-018",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество относится к бронходилататорам?",options:["Цетиризин","Сальбутамол","Прометазин","Мебгидролин"],correctIndex:1,explanation:"Сальбутамол относится к бронходилататорам, тогда как цетиризин, прометазин и мебгидролин — антигистаминные препараты.",difficulty:"medium",tags:["бронходилататоры","препараты"]},{id:"bronchodilators-antihistamines-019",topicId:"bronchodilators-antihistamines",question:"Какое из перечисленных веществ входит в группу бронхорасширяющих средств?",options:["Лоратадин","Дезлоратадин","Фенотерол","Фексофенадин"],correctIndex:2,explanation:"Фенотерол относится к бронходилататорам; лоратадин, дезлоратадин и фексофенадин — антигистаминные препараты.",difficulty:"medium",tags:["бронходилататоры","препараты"]},{id:"bronchodilators-antihistamines-020",topicId:"bronchodilators-antihistamines",question:"Какие два действующих вещества входят в состав комбинированного бронходилататора, указанного в таблице?",options:["Сальбутамол и теофиллин","Эфедрин и эуфиллин","Флутиказон и сальбутамол","Фенотерол и ипратропия бромид"],correctIndex:3,explanation:"Комбинированный препарат содержит фенотерол и ипратропия бромид.",difficulty:"hard",tags:["бронходилататоры","препараты"]},{id:"bronchodilators-antihistamines-021",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество из группы бронходилататоров является производным теофиллина?",options:["Эуфиллин","Эфедрин","Флутиказон","Ипратропия бромид"],correctIndex:0,explanation:"В таблице бронходилататоров наряду с теофиллином указан эуфиллин.",difficulty:"medium",tags:["бронходилататоры","препараты"]},{id:"bronchodilators-antihistamines-022",topicId:"bronchodilators-antihistamines",question:"Каков механизм действия антигистаминных препаратов?",options:["Они разрушают молекулы гистамина в тканях","Они блокируют действие гистамина в организме","Они препятствуют образованию гистамина в клетках","Они выводят гистамин через почки"],correctIndex:1,explanation:"Антигистаминные лекарственные средства блокируют действие гистамина в организме и устраняют вызываемые им проявления.",difficulty:"medium",tags:["антигистаминные","фармакология"]},{id:"bronchodilators-antihistamines-023",topicId:"bronchodilators-antihistamines",question:"Что означает утверждение, что гистамин является эндогенным веществом?",options:["Он поступает в организм только с пищей","Он вырабатывается исключительно бактериями","Он образуется в организме человека","Он синтезируется только в лабораторных условиях"],correctIndex:2,explanation:"Гистамин — эндогенное вещество, то есть образуется в организме человека.",difficulty:"medium",tags:["антигистаминные","терминология"]},{id:"bronchodilators-antihistamines-024",topicId:"bronchodilators-antihistamines",question:"К каким последствиям может привести чрезмерное образование гистамина?",options:["К повышению артериального давления и головной боли","К замедлению сердечного ритма и обморокам","К усилению свёртываемости крови","К сужению бронхов, зуду, кожной сыпи и чиханию"],correctIndex:3,explanation:"Чрезмерное образование гистамина может привести к сужению бронхов, зуду, кожной сыпи, чиханию и другим проявлениям.",difficulty:"medium",tags:["антигистаминные","патогенез"]},{id:"bronchodilators-antihistamines-025",topicId:"bronchodilators-antihistamines",question:"Что является основной причиной повышения уровня гистамина в организме?",options:["Попадание в организм аллергенов","Недостаток витаминов группы B","Переохлаждение организма","Избыточная физическая нагрузка"],correctIndex:0,explanation:"Основная причина повышения уровня гистамина — попадание в организм аллергенов.",difficulty:"medium",tags:["антигистаминные","патогенез"]},{id:"bronchodilators-antihistamines-026",topicId:"bronchodilators-antihistamines",question:"Как называются вещества, вызывающие аллергическую реакцию?",options:["Медиаторы","Аллергены","Антигены","Ферменты"],correctIndex:1,explanation:"Вещества, вызывающие аллергическую реакцию, называются аллергенами.",difficulty:"easy",tags:["антигистаминные","терминология"]},{id:"bronchodilators-antihistamines-027",topicId:"bronchodilators-antihistamines",question:"Какая группа лекарственных препаратов особенно часто выступает в роли аллергенов?",options:["Диуретики","Витамины","Антибиотики","Бета-блокаторы"],correctIndex:2,explanation:"Среди лекарственных препаратов аллергенами особенно часто выступают антибиотики.",difficulty:"medium",tags:["антигистаминные","аллергены"]},{id:"bronchodilators-antihistamines-028",topicId:"bronchodilators-antihistamines",question:"Какие из перечисленных веществ относятся к аллергенам?",options:["Соль, сахар и специи","Витамины группы B","Кислород и азот","Пыльца растений, цитрусовые и шерсть животных"],correctIndex:3,explanation:"К аллергенам относятся пыльца растений, цитрусовые, некоторые лекарственные препараты (особенно антибиотики), шерсть животных и др.",difficulty:"easy",tags:["антигистаминные","аллергены"]},{id:"bronchodilators-antihistamines-029",topicId:"bronchodilators-antihistamines",question:"Уменьшают ли антигистаминные препараты количество гистамина в организме?",options:["Нет, они лишь блокируют его действие, устраняя вызываемые им симптомы","Да, они полностью разрушают гистамин","Да, они снижают его выработку на 50%","Да, они ускоряют выведение гистамина с мочой"],correctIndex:0,explanation:"Антигистаминные препараты не уменьшают количество гистамина — они лишь блокируют его действие в организме, устраняя вызываемые им симптомы.",difficulty:"hard",tags:["антигистаминные","фармакология"]},{id:"bronchodilators-antihistamines-030",topicId:"bronchodilators-antihistamines",question:"Какие побочные эффекты характерны для антигистаминных препаратов?",options:["Тремор рук и тахикардия","Сонливость и лёгкий успокоительный эффект","Возбуждение и бессонница","Повышение артериального давления"],correctIndex:1,explanation:"Побочные эффекты антигистаминных препаратов — сонливость и лёгкий успокоительный эффект.",difficulty:"medium",tags:["антигистаминные","побочные эффекты"]},{id:"bronchodilators-antihistamines-031",topicId:"bronchodilators-antihistamines",question:"В качестве какого дополнительного средства могут применяться антигистаминные препараты?",options:["В качестве жаропонижающего","В качестве мочегонного","В качестве противокашлевого средства","В качестве гемостатического средства"],correctIndex:2,explanation:"Дополнительно антигистаминные препараты применяются как противокашлевое средство и для снижения раздражения в послеоперационный период.",difficulty:"hard",tags:["антигистаминные","показания"]},{id:"bronchodilators-antihistamines-032",topicId:"bronchodilators-antihistamines",question:"В какой период антигистаминные препараты применяются для снижения раздражения?",options:["В период обострения аллергии","В период вакцинации","В период приёма антибиотиков","В послеоперационный период"],correctIndex:3,explanation:"Антигистаминные препараты применяются для снижения раздражения в послеоперационный период.",difficulty:"medium",tags:["антигистаминные","показания"]},{id:"bronchodilators-antihistamines-033",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество относится к антигистаминным препаратам?",options:["Хлоропирамин","Фенотерол","Теофиллин","Ипратропия бромид"],correctIndex:0,explanation:"Хлоропирамин относится к антигистаминным препаратам; фенотерол, теофиллин и ипратропия бромид — бронходилататоры.",difficulty:"medium",tags:["антигистаминные","препараты"]},{id:"bronchodilators-antihistamines-034",topicId:"bronchodilators-antihistamines",question:"Три из четырёх приведённых веществ расширяют бронхи. Какое из них блокирует гистамин?",options:["Эуфиллин","Лоратадин","Сальбутамол","Эфедрин"],correctIndex:1,explanation:"Лоратадин относится к антигистаминным препаратам; эуфиллин, сальбутамол и эфедрин — бронходилататоры.",difficulty:"medium",tags:["антигистаминные","препараты"]},{id:"bronchodilators-antihistamines-035",topicId:"bronchodilators-antihistamines",question:"Из приведённого перечня выберите вещество, которое НЕ является антигистаминным препаратом.",options:["Клемастин","Прометазин","Флутиказон","Цетиризин"],correctIndex:2,explanation:"Флутиказон указан в таблице бронходилататоров, а клемастин, прометазин и цетиризин относятся к антигистаминным препаратам.",difficulty:"hard",tags:["антигистаминные","препараты"]},{id:"bronchodilators-antihistamines-036",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество из числа антигистаминных является левовращающей формой цетиризина?",options:["Дезлоратадин","Фексофенадин","Кетотифен","Левоцетиризин"],correctIndex:3,explanation:"В таблице антигистаминных препаратов наряду с цетиризином указан левоцетиризин.",difficulty:"medium",tags:["антигистаминные","препараты"]},{id:"bronchodilators-antihistamines-037",topicId:"bronchodilators-antihistamines",question:"Какое действующее вещество из таблицы антигистаминных препаратов является производным лоратадина?",options:["Дезлоратадин","Мебгидролин","Монтелукаст","Дифенгидрамин"],correctIndex:0,explanation:"В таблице антигистаминных препаратов наряду с лоратадином указан дезлоратадин.",difficulty:"medium",tags:["антигистаминные","препараты"]},{id:"bronchodilators-antihistamines-038",topicId:"bronchodilators-antihistamines",question:"Какое проявление избытка гистамина затрагивает непосредственно дыхательную систему?",options:["Кожная сыпь","Сужение бронхов","Зуд кожи","Слезотечение"],correctIndex:1,explanation:"Из перечисленных последствий чрезмерного образования гистамина именно сужение бронхов затрагивает дыхательную систему.",difficulty:"medium",tags:["антигистаминные","патогенез"]}];export{i as default};
